"use client";

import { useState, useEffect, useRef } from "react";
import {
  X,
  Trash2,
  Phone,
  Star,
  Edit2,
  Check,
  Loader2,
  MapPin,
  Plus,
  Home,
  Briefcase,
} from "lucide-react";

interface Address {
  id: string;
  name: string;
  phone: string;
  altPhone?: string;
  pincode: string;
  addressLine1: string; // Building
  addressLine2: string; // Locality
  landmark?: string;
  city: string;
  district: string;
  state: string;
  type: "Home" | "Work";
  isDefault: boolean;
}

const FormInput = ({
  label,
  value,
  onChange,
  prefix,
  placeholder,
  inputRef,
}: any) => (
  <div className="space-y-1 w-full">
    <label className="text-[9px] font-black uppercase tracking-widest text-foreground-subtle ml-1">
      {label}
    </label>
    <div className="relative">
      {prefix && (
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-foreground-subtle text-xs font-bold">
          {prefix}
        </span>
      )}
      <input
        ref={inputRef}
        className={`w-full bg-background border border-border rounded-xl py-2.5 text-xs font-bold outline-none focus:border-brand transition-all placeholder:text-foreground-subtle/50 ${
          prefix ? "pl-10" : "px-3"
        }`}
        value={value}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
      />
    </div>
  </div>
);

const AddressFormModal = ({ initialData, onClose, onSave }: any) => {
  const [formData, setFormData] = useState<Partial<Address>>(
    initialData || { type: "Home", isDefault: false }
  );
  const [loading, setLoading] = useState(false);
  const altPhoneRef = useRef<HTMLInputElement>(null);

  // Auto-focus Logic
  useEffect(() => {
    if (formData.phone?.length === 10) {
      altPhoneRef.current?.focus();
    }
  }, [formData.phone]);

  // Pincode Logic
  useEffect(() => {
    if (formData.pincode?.length === 6 && !initialData) {
      setLoading(true);
      fetch(`https://api.postalpincode.in/pincode/${formData.pincode}`)
        .then((res) => res.json())
        .then((data) => {
          if (data[0].Status === "Success") {
            const details = data[0].PostOffice[0];
            setFormData((prev) => ({
              ...prev,
              state: details.State,
              district: details.District,
            }));
          }
        })
        .finally(() => setLoading(false));
    }
  }, [formData.pincode, initialData]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-background/60 backdrop-blur-md"
        onClick={onClose}
      />
      <div className="relative bg-background-elevated w-full max-w-lg rounded-4xl shadow-2xl border border-border flex flex-col max-h-[90vh] overflow-hidden">
        <div className="px-6 py-5 border-b border-border flex justify-between items-center bg-background-elevated sticky top-0 z-10">
          <h2 className="text-lg font-black uppercase tracking-tighter">
            Delivery Address
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-background-muted rounded-full"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-4 overflow-y-auto space-y-6 no-scrollbar">
          {/* SECTION 1: REGION */}
          <div className="grid grid-cols-2 gap-2">
            <div className="relative">
              <FormInput
                label="Pincode"
                placeholder="6 Digits"
                value={formData.pincode || ""}
                onChange={(v: string) =>
                  setFormData({
                    ...formData,
                    pincode: v.replace(/\D/g, "").slice(0, 6),
                  })
                }
              />
              {loading && (
                <Loader2
                  className="absolute right-3 bottom-2.5 animate-spin text-brand"
                  size={16}
                />
              )}
            </div>
            <div className="bg-background-muted rounded-xl px-3 border border-border flex flex-col justify-center">
              <span className="text-[8px] font-black uppercase text-foreground-subtle tracking-widest leading-none mb-1">
                Detected Region
              </span>
              <p className="text-[10px] font-bold truncate text-foreground leading-none">
                {formData.district
                  ? `${formData.district}, ${formData.state}`
                  : "Waiting for Pincode..."}
              </p>
            </div>
          </div>

          {/* SECTION 2: ADDRESS DETAILS */}
          <div className="space-y-4">
            <div className="flex gap-2">
              <FormInput
                label="City / Town"
                placeholder="e.g. Puthanathani"
                value={formData.city || ""}
                onChange={(v: string) => setFormData({ ...formData, city: v })}
              />
              <FormInput
                label="Area / Locality"
                placeholder="Street or Colony"
                value={formData.addressLine2 || ""}
                onChange={(v: string) =>
                  setFormData({ ...formData, addressLine2: v })
                }
              />
            </div>

            <div className="flex gap-2">
              <FormInput
                label="Landmark (Optional)"
                placeholder="Famous place nearby"
                value={formData.landmark || ""}
                onChange={(v: string) =>
                  setFormData({ ...formData, landmark: v })
                }
              />
              <FormInput
                label="Building / House No"
                placeholder="Flat, Floor, House Name"
                value={formData.addressLine1 || ""}
                onChange={(v: string) =>
                  setFormData({ ...formData, addressLine1: v })
                }
              />
            </div>
          </div>

          <hr className="border-border border-dashed" />

          {/* SECTION 3: RECIPIENT */}
          <div className="space-y-4">
            <FormInput
              label="Recipient Name"
              placeholder="Full name"
              value={formData.name || ""}
              onChange={(v: string) => setFormData({ ...formData, name: v })}
            />
            <div className="grid grid-cols-2 gap-4">
              <FormInput
                label="Primary Phone"
                prefix="+91"
                value={formData.phone || ""}
                onChange={(v: string) =>
                  setFormData({
                    ...formData,
                    phone: v.replace(/\D/g, "").slice(0, 10),
                  })
                }
              />
              <FormInput
                inputRef={altPhoneRef}
                label="Alt Phone"
                prefix="+91"
                value={formData.altPhone || ""}
                onChange={(v: string) =>
                  setFormData({
                    ...formData,
                    altPhone: v.replace(/\D/g, "").slice(0, 10),
                  })
                }
              />
            </div>
          </div>

          {/* SECTION 4: TYPES & DEFAULT */}
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4 pt-2">
            <div className="flex bg-background-muted p-1 rounded-full border border-border w-full sm:w-auto">
              {(["Home", "Work"] as const).map((t) => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setFormData({ ...formData, type: t })}
                  className={`flex-1 sm:px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                    formData.type === t
                      ? "bg-background text-foreground shadow-sm"
                      : "text-foreground-subtle"
                  }`}
                >
                  {t === "Home" ? (
                    <Home size={10} className="inline mr-1" />
                  ) : (
                    <Briefcase size={10} className="inline mr-1" />
                  )}
                  {t}
                </button>
              ))}
            </div>

            <label className="flex items-center gap-2 cursor-pointer group w-full sm:w-auto justify-center">
              <div
                className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center transition-all ${
                  formData.isDefault
                    ? "bg-brand border-brand shadow-lg shadow-brand/20"
                    : "border-border"
                }`}
              >
                {formData.isDefault && (
                  <Check size={12} className="text-brand-foreground" />
                )}
              </div>
              <input
                type="checkbox"
                className="hidden"
                checked={formData.isDefault}
                onChange={(e) =>
                  setFormData({ ...formData, isDefault: e.target.checked })
                }
              />
              <span className="text-[10px] font-black text-foreground-subtle uppercase tracking-widest">
                Set Default
              </span>
            </label>
          </div>
        </div>

        <div className="px-6 py-5 border-t border-border bg-background-muted flex gap-4">
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              onSave({
                id: initialData?.id || Date.now().toString(),
                ...formData,
              });
            }}
            className="flex-1 px-6 py-4 rounded-4xl bg-brand text-brand-foreground font-black uppercase text-xs tracking-[0.2em] shadow-xl shadow-brand/20 active:scale-95 transition-all"
          >
            Save Address
          </button>
        </div>
      </div>
    </div>
  );
};

const AddressCard = ({ address, onEdit, onDelete }: any) => (
  <div
    className={`p-6 rounded-4xl border bg-background-elevated flex flex-col min-h-[260px] transition-all duration-300 ${
      address.isDefault
        ? "border-brand ring-1 ring-brand shadow-xl"
        : "border-border shadow-sm"
    }`}
  >
    <div className="flex justify-between items-start mb-6">
      <div className="flex gap-2">
        <span className="px-3 py-1 bg-background-muted text-foreground-muted rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1">
          {address.type === "Home" ? (
            <Home size={10} />
          ) : (
            <Briefcase size={10} />
          )}{" "}
          {address.type}
        </span>
        {address.isDefault && (
          <span className="px-3 py-1 bg-brand text-brand-foreground rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1">
            <Star size={10} fill="currentColor" /> Default
          </span>
        )}
      </div>
      <div className="flex gap-1">
        <button
          onClick={() => onEdit(address)}
          className="p-2 hover:bg-background-muted rounded-full text-foreground-subtle hover:text-foreground transition-colors"
        >
          <Edit2 size={14} />
        </button>
        <button
          onClick={() => onDelete(address.id)}
          className="p-2 hover:bg-destructive/10 rounded-full text-foreground-subtle hover:text-destructive transition-colors"
        >
          <Trash2 size={14} />
        </button>
      </div>
    </div>
    <div className="grow space-y-1.5">
      <h3 className="font-black text-lg leading-tight">{address.name}</h3>
      <p className="text-foreground-muted text-xs leading-relaxed line-clamp-2">
        {address.addressLine1}, {address.addressLine2}{" "}
        {address.landmark && `(Near ${address.landmark})`}
      </p>
      <p className="text-foreground font-bold text-[11px] uppercase tracking-tight">
        {address.city}, {address.district}
      </p>
      <p className="text-foreground-subtle text-[9px] font-black uppercase tracking-widest">
        {address.state} — {address.pincode}
      </p>
      <div className="mt-4 flex items-center gap-2 text-[10px] font-black text-foreground bg-background-muted w-fit px-3 py-1.5 rounded-lg border border-border">
        <Phone size={12} className="text-brand" />{" "}
        <span>+91 {address.phone}</span>
      </div>
    </div>
  </div>
);

export default function AddressPage() {
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAddress, setEditingAddress] = useState<Address | null>(null);

  const handleSave = (data: Address) => {
    let updated = [...addresses];
    if (data.isDefault)
      updated = updated.map((a) => ({ ...a, isDefault: false }));
    const idx = updated.findIndex((a) => a.id === data.id);
    idx >= 0 ? (updated[idx] = data) : updated.push(data);
    setAddresses(updated);
    setIsModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground pb-20 transition-colors">
      <main className="max-w-5xl mx-auto px-4 py-12">
        <div className="flex justify-between items-end mb-10 gap-4">
          <div className="space-y-1">
            <h1 className="text-3xl font-black uppercase tracking-tighter">
              My Addresses
            </h1>
            <p className="text-foreground-muted text-xs font-bold uppercase tracking-widest">
              Delivery Locations
            </p>
          </div>
          <button
            onClick={() => {
              setEditingAddress(null);
              setIsModalOpen(true);
            }}
            className="bg-brand text-brand-foreground px-6 py-3 rounded-4xl font-bold shadow-lg flex items-center gap-2 hover:opacity-90 active:scale-95 transition-all"
          >
            <Plus size={18} /> Add New
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {addresses.map((addr) => (
            <AddressCard
              key={addr.id}
              address={addr}
              onEdit={(a: Address) => {
                setEditingAddress(a);
                setIsModalOpen(true);
              }}
              onDelete={(id: string) =>
                setAddresses(addresses.filter((a) => a.id !== id))
              }
            />
          ))}
        </div>
      </main>

      {isModalOpen && (
        <AddressFormModal
          initialData={editingAddress}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSave}
        />
      )}
    </div>
  );
}
